mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.CON_SEQ DESC) AS RNUM, TB.* FROM ( SELECT A.CON_SEQ AS conSeq, A.CON_NM AS conNm, B.CODE_NM AS codeNm, A.CON_WIDTH AS conWidth, A.CON_HEIGHT AS conHeight, FN_DETAILCODENM(A.CON_SCREEN) AS conScreen, TO_CHAR(A.FRST_REGIST_PNTTM, 'YYYY-MM-DD HH24:MI:SS') AS frstRegistPnttm, ( SELECT COUNT(*) FROM TB_SCHEDULE WHERE CONTENT_CODE = A.CON_SEQ ) AS schCnt FROM TB_CONTENTMUTIL A JOIN LETTCCMMNDETAILCODE B ON A.CON_TYPE = B.CODE WHERE 1=1
AND A.GROUP_ID IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = #{groupId} UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND A.CENTER_ID = #{centerId}
AND A.CON_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND CAST(A.CON_SEQ AS VARCHAR) LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.CON_TYPE = #{conType}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT COALESCE(COUNT(*), 0) FROM TB_CONTENTMUTIL A JOIN LETTCCMMNDETAILCODE B ON A.CON_TYPE = B.CODE WHERE 1=1
AND A.GROUP_ID IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = #{groupId} UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND A.CENTER_ID = #{centerId}
AND A.CON_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND CAST(A.CON_SEQ AS VARCHAR) LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.CON_TYPE = #{conType}

SELECT CON_FILE AS conFile
FROM TB_CONTENTMUTIL
WHERE CON_SEQ = #{conSeq}

SELECT COALESCE(CON_LOCALFILE, 'N') AS conFile
FROM TB_CONTENTMUTIL
WHERE CON_SEQ = #{conSeq}

SELECT CON_SEQ, CON_NM
FROM TB_CONTENTMUTIL
WHERE CON_SEQ != #{conSeq}

mapper.update:
UPDATE TB_CONTENTMUTIL SET
    CON_FILE = #{conFile}
WHERE CON_SEQ = #{conSeq}

UPDATE TB_CONTENTMUTIL SET
    CON_LOCALFILE = #{conLocalfile}
WHERE CON_SEQ = #{conSeq}
